int factorial(int n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

void main() {
  print(factorial(5)); // 120
}

int factorial(int n) {
  int result = 1;
  for (int i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}

import 'dart:math';

abstract class Shape {
  double area();
}

class Circle extends Shape {
  double r;
  Circle(this.r);
  @override
  double area() => pi * r * r;
}

class Rectangle extends Shape {
  double w, h;
  Rectangle(this.w, this.h);
  @override
  double area() => w * h;
}

void main() {
  List<Shape> shapes = [Circle(2), Rectangle(3, 4)];
  for (final s in shapes) {
    print(s.area());
  }
}

